import java.io.*;
import java.util.*;

public class D {
    public static void main(String[] args) throws IOException {
        TokenScanner scanner = new TokenScanner();
        long n = scanner.nextLong();
        long m = scanner.nextLong();
        System.out.println(compute(n, m));
    }

    static class TokenScanner {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokenizer;

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) throw new NoSuchElementException("End of input");
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    static long compute(long n, long m) {
        if (m < n) {
            long temp = n;
            n = m;
            m = temp;
        }
        if (n == 1) return specialRow(m);
        if (n == 2) return specialTwoRows(m);
        return 2 * (n * m / 2);
    }

    static long specialRow(long m) {
        long ans = 6 * (m / 6);
        long mod = m % 6;
        if (mod == 5) return ans + 4;
        if (mod == 4) return ans + 2;
        return ans;
    }

    static long specialTwoRows(long m) {
        if (m == 3) return 4;
        if (m == 7) return 12;
        if (m < 3) return 0;
        return 2 * m;
    }
}
